create extension if not exists pgcrypto;create schema if not exists dau_an_ket_noi;
create table if not exists dau_an_ket_noi.admins(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text not null,created_at timestamptz default now());
create table if not exists dau_an_ket_noi.events(id uuid primary key default gen_random_uuid(),owner_id uuid references dau_an_ket_noi.admins(id),slug text unique not null,title text not null,partner_name text default '',event_date date not null,description text default '',status text not null default 'draft' check(status in('draft','processing','ready','active','inactive','failed')),visibility text not null default 'unlisted',reference_image_url text,reference_image_public_id text,thumbnail_url text,video_url text,video_public_id text,target_url text,image_width int,image_height int,video_duration real,video_width int,video_height int,embedding jsonb,embedding_model text,embedding_version text,embedding_dimension int,best_video_frame_time real,registration_similarity real,feature_match_count int,inlier_count int,inlier_ratio real,processing_error text,created_at timestamptz default now(),updated_at timestamptz default now(),activated_at timestamptz);
create index if not exists dakn_events_status_idx on dau_an_ket_noi.events(status);
create index if not exists dakn_events_owner_idx on dau_an_ket_noi.events(owner_id);
